7	 * INCLUDING BUT NOT LIMITED TO NON-INFRINGEMENT, MERCHANTABILITY, OR FITNESS FOR A PARTICULAR PURPOSE.
8	 * See LICENSE in the root of the software repository for the full text of the License.
9	 */
10	
11	#include <stdlib.h>
12	#include <errno.h>
13	#include <unistd.h>
14	#include <fcntl.h>
15	#include <pthread.h>
16	#include <sys/ioctl.h>
17	#include <stdbool.h>
18	
19	#include "securec.h"
20	#include "davinci_interface.h"
21	
22	#include "uda_cmd.h"
23	#include "uda_user_kernel_api.h"
24	#include "uda_user.h"
25	#include "pbl_uda_user.h"
26	
27	#ifndef ASCEND_BACKUP_DEV_NUM
28	#define ASCEND_BACKUP_DEV_NUM 0
29	#endif
30	
31	#define UDA_BUFF_LEN 32
32	#define MAX_REMOTE_UDEV_NUM (1124 + 16 * ASCEND_BACKUP_DEV_NUM)
33	#define UDA_HOST_ID 65
34	
35	#define UDA_DEVICE_PATH "/dev/"
36	#define UDA_DEVICE_NAME "davinci"
37	
38	#ifdef STATIC_SKIP
39	#define STATIC
40	#else
41	#define STATIC static
42	#endif
43	
44	#ifdef EMU_ST
45	int uda_file_access(const char *pathname, int flags);
46	int uda_file_open(const char *pathname, int flags);
47	int uda_file_close(int fd);
48	int uda_ioctl(int fd, unsigned long cmd, void *para);
49	#else
50	#define uda_file_access access
51	#define uda_file_open open
52	#define uda_file_close close
53	#define uda_ioctl(fd, cmd, ...) ioctl((fd), (cmd), ##__VA_ARGS__)
54	#endif
55	
56	static bool uda_is_init = false;
57	static int uda_dev_fd = -1;
58	static pid_t uda_cur_pid = -1;
59	static unsigned int uda_dev_num_davinci = 0;
60	static unsigned int uda_dev_num_kunpeng = 0;
61	static struct uda_user_info user_info;
62	static struct uda_logic_dev *logic_dev = NULL;
63	static pthread_mutex_t uda_fd_mutex = PTHREAD_MUTEX_INITIALIZER;
64	
65	static bool uda_is_admin(void)
66	{
67	    return (user_info.admin_flag == 1);
68	}
69	
70	static bool uda_is_in_local(void)
71	{
72	    return (user_info.local_flag == 1);
73	}
74	
75	static bool uda_is_support_udev_mng(void)
76	{
77	    return (user_info.support_udev_mng == 1);
78	}
79	
80	static uint32_t uda_get_max_dev_num(void)
81	{
82	    return uda_is_admin() ? user_info.max_udev_num : user_info.max_dev_num;
83	}
84	
85	static int uda_dev_access(uint32_t *dev_num)
86	{
87	    uint32_t i;
88	    int ret;
89	
90	    *dev_num = 0;
91	    for (i = 0; i < user_info.max_udev_num; i++) {
92	        char name[UDA_BUFF_LEN];
93	        int fd;
94	        if (sprintf_s(name, UDA_BUFF_LEN, "%s%s%u", UDA_DEVICE_PATH, UDA_DEVICE_NAME, i) <= 0) {
95	            uda_err("Invalid name.\n");
96	            return DRV_ERROR_INVALID_VALUE;
97	        }
98	        if (uda_file_access(name, O_RDONLY) != 0) {
99	            continue;
100	        }
101	
102	        fd = uda_file_open(name, O_RDONLY); /* open device set namespace */
103	        if (fd >= 0) {
104	            uda_file_close(fd);
105	            (*dev_num)++;
106	        } else {
107	            if (errno == EBUSY) {
108	                ret = DRV_ERROR_RESOURCE_OCCUPIED;
109	            } else if (errno == ENODEV) {
110	                ret = DRV_ERROR_NO_DEVICE;
111	            } else {
112	                ret = DRV_ERROR_INNER_ERR;
113	            }
114	            uda_err("Dev open failed. (dev=%s; errno=%d; ret=%d)\n", name, errno, ret);
115	            return ret;
116	        }
117	    }
118	
119	    return 0;
120	}
121	
122	static int uda_char_dev_open(void)
123	{
124	    struct davinci_intf_open_arg arg;
125	    int ret;
126	
127	    arg.device_id = 0;
128	    ret = strcpy_s(arg.module_name, DAVINIC_MODULE_NAME_MAX, UDA_CHAR_DEV_NAME);
129	    if (ret != 0) {
130	        uda_err("Strcpy_s failed. (ret=%d)\n", ret);
131	        return DRV_ERROR_INVALID_VALUE;
132	    }
133	
134	    uda_dev_fd = uda_file_open(davinci_intf_get_dev_path(), O_RDWR | O_CLOEXEC);
135	    if (uda_dev_fd < 0) {
136	        uda_err("Open failed. (fd=%d; errno=%d)\n", uda_dev_fd, errno);
137	        return DRV_ERROR_INNER_ERR;
138	    }
139	
140	    ret = uda_ioctl(uda_dev_fd, DAVINCI_INTF_IOCTL_OPEN, &arg);
141	    if (ret != 0) {
142	        uda_err("Ioctrl failed. (fd=%d; errno=%d)\n", uda_dev_fd, errno);
143	        uda_file_close(uda_dev_fd);
144	        uda_dev_fd = -1;
145	        return DRV_ERROR_IOCRL_FAIL;
146	    }
147	    uda_cur_pid = getpid();
148	
149	    uda_info("The fd and pid info: (fd=%d; pid=%d)\n", uda_dev_fd, uda_cur_pid);
150	    return DRV_ERROR_NONE;
151	}
152	
153	static void uda_char_dev_close(void)
154	{
155	    struct davinci_intf_close_arg arg;
156	    int ret;
157	
158	    arg.device_id = 0;
159	    ret = strcpy_s(arg.module_name, DAVINIC_MODULE_NAME_MAX, UDA_CHAR_DEV_NAME);
160	    if (ret != 0) {
161	        uda_err("Strcpy_s failed. (ret=%d)\n", ret);
162	        return;
163	    }
164	
165	    ret = uda_ioctl(uda_dev_fd, DAVINCI_INTF_IOCTL_CLOSE, &arg);
166	    if (ret != 0) {
167	        uda_err("Ioctrl failed. (fd=%d; errno=%d)\n", uda_dev_fd, errno);
168	    }
169	
170	    uda_file_close(uda_dev_fd);
171	    uda_dev_fd = -1;
172	
173	    return;
174	}
175	
176	static int uda_cmd_ioctl(unsigned long cmd, void *para)
177	{
178	    int ret;
179	
180	    (void)pthread_mutex_lock(&uda_fd_mutex);
181	    if (uda_dev_fd < 0 || uda_cur_pid != getpid()) {
182	        ret = uda_char_dev_open();
183	        if (ret != 0) {
184	            (void)pthread_mutex_unlock(&uda_fd_mutex);
185	            return ret;
186	        }
187	    }
188	    (void)pthread_mutex_unlock(&uda_fd_mutex);
189	
190	    do {
191	        ret = uda_ioctl(uda_dev_fd, cmd, para);
192	    } while ((ret == -1) && (errno == EINTR));
193	
194	    if (ret < 0) {
195	        if (errno == EBUSY) {
196	            ret = DRV_ERROR_RESOURCE_OCCUPIED;
197	        } else if (errno == ENODEV) {
198	            ret = DRV_ERROR_NO_DEVICE;
199	        } else if (errno == ENOMEM) {
200	            ret = DRV_ERROR_OUT_OF_MEMORY;
201	        } else {
202	            ret = DRV_ERROR_IOCRL_FAIL;
203	        }
204	        share_log_read_err(HAL_MODULE_TYPE_DEV_MANAGER);
205	        return ret;
206	    }
207	
208	    return DRV_ERROR_NONE;
209	}
210	
211	static int uda_get_user_info(void)
212	{
213	    return uda_cmd_ioctl(UDA_GET_USER_INFO, &user_info);
214	}
215	
216	static int uda_init_dev_table(uint32_t dev_num)
217	{
218	    struct uda_setup_table info;
219	
220	    info.dev_num = dev_num;
221	    return uda_cmd_ioctl(UDA_SETUP_DEV_TABLE, &info);
222	}
223	
224	static int uda_get_dev_list(uint32_t start_devid, uint32_t end_devid)
225	{
226	    struct uda_dev_list info;
227	
228	    info.start_devid = start_devid;
229	    info.end_devid = end_devid;
230	    info.logic_dev = logic_dev;
231	    return uda_cmd_ioctl(UDA_GET_DEV_LIST, &info);
232	}
233	
234	static int uda_trans_devid(unsigned long cmd, uint32_t raw_devid, uint32_t *trans_devid)
235	{
236	    struct uda_devid_trans info;
237	    int ret;
238	
239	    info.raw_devid = raw_devid;
240	
241	    ret = uda_cmd_ioctl(cmd, &info);
242	    if (ret != DRV_ERROR_NONE) {
243	        return ret;
244	    }
245	
246	    *trans_devid = info.trans_devid;
247	
248	    return DRV_ERROR_NONE;
249	}
250	
251	static uint32_t uda_get_dev_num_from_dev_list(struct uda_logic_dev *dev, uint32_t max_dev_num, uint32_t hw_type)
252	{
253	    uint32_t dev_num = 0, i;
254	
255	    for (i = 0; i < max_dev_num; i++) {
256	        if ((dev[i].valid == 1) && (dev[i].hw_type == hw_type)) {
257	            dev_num++;
258	        }
259	    }
260	
261	    return dev_num;
262	}
263	
264	static int _uda_init(void)
265	{
266	    uint32_t access_dev_num, dev_num, i;
267	    int ret;
268	
269	    ret = uda_get_user_info();
270	    if (ret != 0) {
271	        uda_err("Get user info failed. (ret=%d)\n", ret);
272	        return ret;
273	    }
274	
275	    if (!uda_is_admin()) {
276	        ret = uda_dev_access(&access_dev_num);
277	        if (ret != 0) {
278	            return ret;
279	        }
280	    } else {
281	        access_dev_num = user_info.max_dev_num;
282	    }
283	
284	    dev_num = uda_get_max_dev_num();
285	    if (logic_dev == NULL) {
286	        logic_dev = malloc(dev_num * sizeof(struct uda_logic_dev));
287	        if (logic_dev == NULL) {
288	            uda_err("Alloc logic devctx failed. (dev_num=%u)\n", dev_num);
289	            return DRV_ERROR_OUT_OF_MEMORY;
290	        }
291	    }
292	
293	    for (i = 0; i < dev_num; i++) {
294	        logic_dev[i].valid = 0;
295	    }
296	
297	    ret = uda_init_dev_table(access_dev_num);
298	    if (ret != 0) {
299	        uda_err("Init dev table failed. (ret=%d; access_dev_num=%u)\n", ret, access_dev_num);
300	        return ret;
301	    }
302	
303	    ret = uda_get_dev_list(0, dev_num);
304	    if (ret != 0) {
305	        uda_err("Get dev list failed. (ret=%d)\n", ret);
306	        return ret;
307	    }
308	
309	    uda_dev_num_davinci = uda_get_dev_num_from_dev_list(logic_dev, user_info.max_dev_num, UDA_HW_DAVINCI);
310	    uda_dev_num_kunpeng = uda_get_dev_num_from_dev_list(logic_dev, user_info.max_dev_num, UDA_HW_KUNPENG);
311	
312	    uda_info("User info. (admin_flag=%u; local_flag=%u; max_dev_num=%u; max_udev_num=%u; "
313	             "uda_dev_num_davinci=%u; uda_dev_num_kunpeng=%u)\n",
314	        user_info.admin_flag,
315	        user_info.local_flag,
316	        user_info.max_dev_num,
317	        user_info.max_udev_num,
318	        uda_dev_num_davinci,
319	        uda_dev_num_kunpeng);
320	
321	    return 0;
322	}
323	
324	static int uda_init(void)
325	{
326	    static pthread_mutex_t init_mutex = PTHREAD_MUTEX_INITIALIZER;
327	    int ret = 0;
328	
329	    if (uda_is_init) {
330	        return 0;
331	    }
332	
333	    (void)pthread_mutex_lock(&init_mutex);
334	    if (!uda_is_init) {
335	        ret = _uda_init();
336	        if (ret == 0) {
337	            uda_is_init = true;
338	        }
339	    }
340	    (void)pthread_mutex_unlock(&init_mutex);
341	
342	    return ret;
343	}
