int uda_get_devid_by_udevid(uint32_t udevid, uint32_t *devid)
{
    uint32_t i, max_dev_num;
    int ret = uda_init();
    if (ret != 0) {
        return ret;
    }

    if (devid == NULL) {
        uda_err("Null ptr\n");
        return DRV_ERROR_INVALID_VALUE;
    }

    max_dev_num = uda_get_max_dev_num();
    for (i = 0; i < max_dev_num; i++) {
