{
    int ret;

    if (flag == NULL) {
        uda_err("flag in NULL\n");
        return -EINVAL;
    }

    ret = uda_cmd_ioctl(UDA_GET_RAW_PROC_IS_CONTAIN_FLAG, flag);
    if (ret != DRV_ERROR_NONE) {
        uda_err("ioctl failed. (ret=%d)\n", ret);
